// Every page gets the same plugins; each page can switch one off or tune it.
Page.use(Tabs, Status, Settings, Content);
Status.use(Voice);                 // a plugin can have plugins
Content.use(Previews, AutoScroll); // the content list's own plugins

// One page changes its own tree. Each call saves one line in its page.jsonl:
page.plugins.set({ tabs: { enabled: false } });
page.plugins.status.plugins.set({ voice: { enabled: true } });
page.plugins.set({ content: { config: { columns: 2 } } });

page.overrides;   // plain data: { tabs: {enabled: false}, status: {plugins: {voice: …}} }

// Save: this page's switches, config, layout and starter cards become a template.
page.save_template("dashboard");

// Adopt: one call on another page.
other.set({ template: "dashboard" });

// What the page then reads, lowest layer first:
//   1. Page's class defaults   (Page.use …)
//   2. the template            (dashboard: tabs on, voice off, 2 columns, 3 starter cards)
//   3. the page's own choices  (its own page.plugins.set lines)
// Change the template later and every page using it follows,
// except where a page made its own choice.
